def paragraphs(pairs):
    return {"paragraphs": [{"zh": zh, "en": en} for zh, en in pairs]}

for relative, update in UPDATES.items():
    path = ROOT / relative
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    data["application_scenarios_and_threat_model"]["application_scenarios"] = paragraphs(update["scenario"])
    data["application_scenarios_and_threat_model"]["threat_model"]["attacker_model"] = paragraphs(update["attacker"])
    data["application_scenarios_and_threat_model"]["threat_model"]["defender_model"] = paragraphs(update["defender"])
    data["research"]["limitations"] = paragraphs(update["limits"])
    for ref in update.get("refs", []):
        if ref not in data["evidence"]["reference_refs"]:
            data["evidence"]["reference_refs"].append(ref)
    data["lifecycle"]["version"] = "1.0.0"
    data["lifecycle"]["modified"] = "2026-09-12"
    path.write_text(yaml.safe_dump(data, allow_unicode=True, sort_keys=False, width=140), encoding="utf-8")
